import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    greetings = input[1:]

    def is_stylish(subset):
        for i in range(len(subset)):
            for j in range(len(subset)):
                if i != j and subset[i] in subset[j]:
                    return False
        return True

    max_size = 0
    best_subset = []

    for i in range(1, 1 << n):
        subset = [greetings[j] for j in range(n) if (i & (1 << j))]
        if is_stylish(subset) and len(subset) > max_size:
            max_size = len(subset)
            best_subset = [j + 1 for j in range(n) if (i & (1 << j))]

    print(max_size)
    print(' '.join(map(str, best_subset)))

main()
